widget.solution:
import numpy as np
from statsmodels.tsa.stattools import adfuller, coint

def eg_decision(y, x, alpha=0.05):
    """Return (statistic, p-value, reject) from coint(y, x)."""
    stat, p, crit = coint(y, x)
    return round(float(stat), 4), round(float(p), 4), bool(p < alpha)


def wrong_decision(y, x):
    """The trap: ADF on the OLS residual, read with adfuller's own p-value."""
    beta, alpha = np.polyfit(x, y, 1)
    res = np.asarray(y) - alpha - beta * np.asarray(x)
    p = adfuller(res, autolag="AIC")[1]
    return bool(p < 0.05)
